const FogGrid& ScriptSession::fog(unsigned owner) {
    if(owner>=16)throw std::runtime_error("Fog player outside classic range");auto& grid=fogGrids_[owner];if(!grid)grid=std::make_unique<FogGrid>(requireWorld().data().terrain);if(grid->stamp==fogRevision_)return *grid;grid->begin();auto modifiers=[&](bool after){for(auto& [id,modifier]:fogModifiers_)if(modifier->enabled && modifier->afterUnits==after && (modifier->owner==owner || (modifier->shared && (config_.players[modifier->owner].alliances[owner]&(1u<<5))))){if(modifier->radial)grid->circle(modifier->center,modifier->radius,modifier->state);else grid->rect(modifier->rect,modifier->state);}};modifiers(false);
    for(auto& [id,u]:units_)if(!u->hidden() && std::bit_cast<float>(u->life.bits())>0 && (u->owner==owner || u->soulVisionPlayer==owner || u->visionPlayers.contains(owner) || (exposedPlayers_[u->owner]&(1u<<owner)) || buffSharedVision(*u,owner) || (config_.players[u->owner].alliances[owner]&(1u<<5)))){float sight=definitions().number(u->type,"UnitBalance",(requireWorld().clock().daytime() || u->equipment.ultravision || u->technology.ultravision)?"sight":"nsight",800)+u->equipment.sight+u->technology.sight;if(sight>0)grid->circle({u->x,u->y},jass::Real::fromBits(std::bit_cast<std::uint32_t>(sight)),4);}for(auto& [id,owl]:sentinels_)if(owl.owner==owner || (config_.players[owl.owner].alliances[owner]&(1u<<5))){float radius=owl.arrived?owl.perchRadius:owl.flightRadius;if(radius>0)grid->circle(owl.point,jass::Real::fromBits(std::bit_cast<std::uint32_t>(radius)),4);}for(auto& [id,area]:revealAreas_)if(area.active && area.expires>simulationTime_ && (area.owner==owner || (config_.players[area.owner].alliances[owner]&(1u<<5)))){if(area.whole)grid->rect(requireWorld().bounds(),4);else grid->circle(area.point,jass::Real::fromBits(std::bit_cast<std::uint32_t>(area.radius)),4);}modifiers(true);grid->finish(fogEnabled_,fogMaskEnabled_,requireWorld().environment().fogBoundary);grid->stamp=fogRevision_;return *grid;
}
Bytes ScriptSession::encodeFogState(const jass::StableHandleMap& encodeHandle) const {
    if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Fog snapshot requires a quiescent initialized local session");constexpr size_t budget=24u*1024u*1024u;std::vector<std::uint32_t> handles;for(size_t i=0;i<objects_.size();++i)if(objects_[i].kind==NativeKind::Fog)handles.push_back(handleBase+std::uint32_t(i));if(handles.size()>8192 || (!handles.empty() && !encodeHandle))throw std::runtime_error("Fog snapshot requires mapping and valid budget");SnapshotWriter out(budget-64);out.u32(tag("SFOG"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));if(fogTicks_!=std::uint64_t(simulationTime_*32))throw std::runtime_error("Fog tick count differs from simulation clock");out.u64(fogTicks_);out.u32((fogEnabled_?1u:0u)|(fogMaskEnabled_?2u:0u)|(world_->environment().fogBoundary?4u:0u));for(auto exposed:exposedPlayers_){if(exposed>0xffff)throw std::runtime_error("Invalid exposed player flags");out.u32(exposed);}out.size(handles.size());std::set<std::uint32_t> stable;
    for(auto id:handles){auto mapped=encodeHandle("fogmodifier",id);if(!mapped || !stable.insert(mapped).second)throw std::runtime_error("Invalid fog modifier mapping");auto& obj=objects_[id-handleBase];out.u32(mapped);out.u32(obj.alive?1:0);if(!obj.alive)continue;auto found=fogModifiers_.find(id);if(found==fogModifiers_.end() || !found->second || std::get<std::shared_ptr<FogModifier>>(obj.state)!=found->second)throw std::runtime_error("Invalid fog modifier identity");auto& m=*found->second;if(m.owner>=16 || (m.state!=1 && m.state!=2 && m.state!=4))throw std::runtime_error("Invalid fog modifier state");out.u32(m.owner);out.u32(m.state);out.u32((m.radial?1u:0u)|(m.shared?2u:0u)|(m.afterUnits?4u:0u)|(m.enabled?8u:0u));for(auto value:{m.rect.minX,m.rect.minY,m.rect.maxX,m.rect.maxY,m.center.x,m.center.y,m.radius}){if(!std::isfinite(std::bit_cast<float>(value.bits())))throw std::runtime_error("Invalid fog modifier coordinate");out.u32(value.bits());}if(std::bit_cast<float>(m.radius.bits())<0)throw std::runtime_error("Invalid fog modifier radius");}
    for(auto& grid:fogGrids_){out.u32(grid?1:0);if(!grid)continue;if(grid->explored_.size()!=grid->visible_.size())throw std::runtime_error("Fog grid dimensions differ");for(size_t i=0;i<grid->explored_.size();++i)if(grid->visible_[i] && !grid->explored_[i])throw std::runtime_error("Visible fog cell is unexplored");out.u32(grid->width);out.u32(grid->height);out.u32(grid->stamp==fogRevision_?1:0);auto pack=[&](const Bytes& values){Bytes packed((values.size()+7)/8);for(size_t i=0;i<values.size();++i){if(values[i]>1)throw std::runtime_error("Invalid fog cell");packed[i/8]|=values[i]<<(i%8);}out.size(packed.size());out.raw(packed);};pack(grid->explored_);pack(grid->visible_);}return sealSnapshot(out.finish(),budget);
}
std::map<std::uint32_t,std::uint32_t> ScriptSession::rebuildFogState(std::span<const std::uint8_t> bytes) {
    if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || fogStateRebuilt_ || std::any_of(objects_.begin(),objects_.end(),[](const auto& object){return object.kind==NativeKind::Fog;}) || !fogModifiers_.empty() || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Fog rebuild requires a quiescent local session before map main");constexpr size_t budget=24u*1024u*1024u;Binary in(openSnapshot(bytes,budget));in.expect(tag("SFOG"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("Fog snapshot map or clock mismatch");auto ticks=snapshotU64(in);auto settings=in.u32();if(ticks!=std::uint64_t(simulationTime_*32) || settings>7)throw std::runtime_error("Invalid fog settings");std::array<std::uint32_t,16> exposed{};for(auto& value:exposed){value=in.u32();if(value>0xffff)throw std::runtime_error("Invalid exposed player flags");}struct Saved {std::uint32_t id;bool alive;FogModifier value;};std::vector<Saved> saved;std::set<std::uint32_t> stable;auto count=in.u32();if(count>8192)throw std::runtime_error("Fog modifier count exceeds budget");for(unsigned i=0;i<count;++i){Saved entry{};entry.id=in.u32();auto alive=in.u32();if(!entry.id || !stable.insert(entry.id).second || alive>1)throw std::runtime_error("Invalid fog modifier identity");entry.alive=alive!=0;if(entry.alive){auto& m=entry.value;m.owner=in.u32();m.state=in.u32();auto flags=in.u32();if(m.owner>=16 || (m.state!=1 && m.state!=2 && m.state!=4) || flags>15)throw std::runtime_error("Invalid fog modifier state");m.radial=flags&1;m.shared=flags&2;m.afterUnits=flags&4;m.enabled=flags&8;for(auto target:{&m.rect.minX,&m.rect.minY,&m.rect.maxX,&m.rect.maxY,&m.center.x,&m.center.y,&m.radius}){*target=jass::Real::fromBits(in.u32());if(!std::isfinite(std::bit_cast<float>(target->bits())))throw std::runtime_error("Invalid fog modifier coordinate");}if(std::bit_cast<float>(m.radius.bits())<0)throw std::runtime_error("Invalid fog modifier radius");}saved.push_back(entry);}
    std::array<std::unique_ptr<FogGrid>,16> grids;std::array<bool,16> valid{};for(unsigned player=0;player<16;++player){auto present=in.u32();if(present>1)throw std::runtime_error("Invalid fog grid flag");if(!present)continue;auto grid=std::make_unique<FogGrid>(world_->data().terrain);auto width=in.u32(),height=in.u32(),current=in.u32();if(width!=grid->width || height!=grid->height || current>1)throw std::runtime_error("Fog grid dimensions differ");valid[player]=current!=0;auto unpack=[&](Bytes& values){auto length=in.u32();if(length!=(values.size()+7)/8)throw std::runtime_error("Invalid fog grid size");auto packed=in.take(length);if(values.size()%8 && (packed.back()>>(values.size()%8)))throw std::runtime_error("Invalid fog grid padding");for(size_t i=0;i<values.size();++i)values[i]=(packed[i/8]>>(i%8))&1;};unpack(grid->explored_);unpack(grid->visible_);for(size_t i=0;i<grid->explored_.size();++i)if(grid->visible_[i] && !grid->explored_[i])throw std::runtime_error("Visible fog cell is unexplored");grid->finish(settings&1,settings&2,settings&4);grids[player]=std::move(grid);}in.finish();
    struct Guard {bool& failed;bool done=false;~Guard(){if(!done)failed=true;}}guard{failed_};std::map<std::uint32_t,std::uint32_t> result;for(auto& entry:saved){std::uint32_t id;if(entry.alive){auto h=create(NativeKind::Fog);id=h.bits;auto modifier=std::make_shared<FogModifier>(entry.value);std::get<std::shared_ptr<FogModifier>>(object(h,NativeKind::Fog).state)=modifier;fogModifiers_.emplace(id,std::move(modifier));}else{id=handleBase+std::uint32_t(objects_.size());objects_.push_back(Object{NativeKind::Fog,false,std::monostate{}});}result.emplace(entry.id,id);}fogEnabled_=settings&1;fogMaskEnabled_=settings&2;world_->environment().fogBoundary=settings&4;exposedPlayers_=exposed;fogTicks_=ticks;++fogRevision_;for(unsigned i=0;i<16;++i)if(grids[i])grids[i]->stamp=valid[i]?fogRevision_:0;fogGrids_=std::move(grids);fogStateRebuilt_=true;guard.done=true;return result;
}
void ScriptSession::bindFogNatives() {
    bind("EnableWorldFogBoundary","nothing",{"boolean"},[this](auto& vm,auto a){auto& flag=requireWorld().environment().fogBoundary;bool value=a[0].bits!=0;if(flag!=value){flag=value;++fogRevision_;}return vm.nothing();});
    auto setState=[this](unsigned owner,unsigned state,bool shared,WorldRect rect,WorldPoint center,jass::Real radius,bool radial){
        if(state!=1 && state!=2 && state!=4)throw std::runtime_error("Invalid fog state");
        auto finite=[](jass::Real value){return std::isfinite(std::bit_cast<float>(value.bits()));};
        if(radial){if(!finite(center.x) || !finite(center.y) || !finite(radius) || std::bit_cast<float>(radius.bits())<0)throw std::runtime_error("Invalid fog circle");}
        else if(!finite(rect.minX) || !finite(rect.minY) || !finite(rect.maxX) || !finite(rect.maxY))throw std::runtime_error("Invalid fog rectangle");
        std::array<bool,16> recipients{};for(unsigned player=0;player<16;++player)if(player==owner || (shared && (config_.players[owner].alliances[player]&(1u<<5)))){fog(player);recipients[player]=true;}
        auto previous=fogRevision_++;for(auto& grid:fogGrids_)if(grid && grid->stamp==previous)grid->stamp=fogRevision_;for(unsigned player=0;player<16;++player)if(recipients[player]){auto& grid=*fogGrids_[player];if(radial)grid.circle(center,radius,state);else grid.rect(rect,state);grid.finish(fogEnabled_,fogMaskEnabled_,requireWorld().environment().fogBoundary);}
    };
    bind("SetFogStateRect","nothing",{"player","fogstate","rect","boolean"},[this,setState](auto& vm,auto a){setState(playerId(a[0]),a[1].bits,a[3].bits!=0,std::get<WorldRect>(object(a[2],NativeKind::Rect).state),{},{},false);return vm.nothing();});
    bind("SetFogStateRadius","nothing",{"player","fogstate","real","real","real","boolean"},[this,setState](auto& vm,auto a){setState(playerId(a[0]),a[1].bits,a[5].bits!=0,{},WorldPoint{jass::Real::fromBits(a[2].bits),jass::Real::fromBits(a[3].bits)},jass::Real::fromBits(a[4].bits),true);return vm.nothing();});
    bind("SetFogStateRadiusLoc","nothing",{"player","fogstate","location","real","boolean"},[this,setState](auto& vm,auto a){setState(playerId(a[0]),a[1].bits,a[4].bits!=0,{},std::get<WorldPoint>(object(a[2],NativeKind::Location).state),jass::Real::fromBits(a[3].bits),true);return vm.nothing();});
    auto make=[this](unsigned owner,unsigned state,bool shared,bool after,WorldRect rect,WorldPoint center,jass::Real radius,bool radial){if(state!=1 && state!=2 && state!=4)throw std::runtime_error("Invalid fog state");auto value=std::make_shared<FogModifier>();value->owner=owner;value->state=state;value->shared=shared;value->afterUnits=after;value->rect=rect;value->center=center;value->radius=radius;value->radial=radial;auto handle=create(NativeKind::Fog);std::get<std::shared_ptr<FogModifier>>(object(handle,NativeKind::Fog).state)=value;fogModifiers_[handle.bits]=std::move(value);return handle;};
    bind("CreateFogModifierRect","fogmodifier",{"player","fogstate","rect","boolean","boolean"},[this,make](auto&,auto a){return make(playerId(a[0]),a[1].bits,a[3].bits!=0,a[4].bits!=0,std::get<WorldRect>(object(a[2],NativeKind::Rect).state),{},jass::Real{},false);});
    bind("CreateFogModifierRadius","fogmodifier",{"player","fogstate","real","real","real","boolean","boolean"},[this,make](auto&,auto a){auto radius=std::bit_cast<float>(a[4].bits);if(!std::isfinite(radius) || radius<0)throw std::runtime_error("Invalid fog modifier radius");return make(playerId(a[0]),a[1].bits,a[5].bits!=0,a[6].bits!=0,{},WorldPoint{jass::Real::fromBits(a[2].bits),jass::Real::fromBits(a[3].bits)},jass::Real::fromBits(a[4].bits),true);});
    bind("CreateFogModifierRadiusLoc","fogmodifier",{"player","fogstate","location","real","boolean","boolean"},[this,make](auto&,auto a){auto radius=std::bit_cast<float>(a[3].bits);if(!std::isfinite(radius) || radius<0)throw std::runtime_error("Invalid fog modifier radius");return make(playerId(a[0]),a[1].bits,a[4].bits!=0,a[5].bits!=0,{},std::get<WorldPoint>(object(a[2],NativeKind::Location).state),jass::Real::fromBits(a[3].bits),true);});
    for(auto [name,start]:std::initializer_list<std::pair<const char*,bool>>{{"FogModifierStart",true},{"FogModifierStop",false}})bind(name,"nothing",{"fogmodifier"},[this,start](auto& vm,auto a){if(alive(a[0].bits,NativeKind::Fog)){std::get<std::shared_ptr<FogModifier>>(object(a[0],NativeKind::Fog).state)->enabled=start;++fogRevision_;}return vm.nothing();});
    bind("DestroyFogModifier","nothing",{"fogmodifier"},[this](auto& vm,auto a){if(alive(a[0].bits,NativeKind::Fog)){fogModifiers_.erase(a[0].bits);destroy(a[0],NativeKind::Fog);++fogRevision_;}return vm.nothing();});
    for(auto [name,state]:std::initializer_list<std::pair<const char*,unsigned>>{{"IsVisibleToPlayer",4},{"IsFoggedToPlayer",2},{"IsMaskedToPlayer",1}})bind(name,"boolean",{"real","real","player"},[this,state](auto& vm,auto a){return vm.boolean(fog(playerId(a[2])).state({jass::Real::fromBits(a[0].bits),jass::Real::fromBits(a[1].bits)})==state);});
    for(auto [name,state]:std::initializer_list<std::pair<const char*,unsigned>>{{"IsLocationVisibleToPlayer",4},{"IsLocationFoggedToPlayer",2},{"IsLocationMaskedToPlayer",1}})bind(name,"boolean",{"location","player"},[this,state](auto& vm,auto a){auto point=std::get<WorldPoint>(object(a[0],NativeKind::Location).state);return vm.boolean(fog(playerId(a[1])).state(point)==state);});
    bind("IsUnitVisible","boolean",{"unit","player"},[this](auto& vm,auto a){return vm.boolean(unitVisibleTo(a[0].bits,playerId(a[1])));});
    bind("IsUnitInvisible","boolean",{"unit","player"},[this](auto& vm,auto a){return vm.boolean(unitInvisibleTo(a[0].bits,playerId(a[1])));});
    bind("IsUnitDetected","boolean",{"unit","player"},[this](auto& vm,auto a){return vm.boolean(unitDetected(a[0].bits,playerId(a[1])));});
    for(auto [name,state]:std::initializer_list<std::pair<const char*,unsigned>>{{"IsUnitFogged",2},{"IsUnitMasked",1}})bind(name,"boolean",{"unit","player"},[this,state](auto& vm,auto a){if(!alive(a[0].bits,NativeKind::Unit))return vm.boolean(false);auto u=units_.at(a[0].bits);return vm.boolean(fog(playerId(a[1])).state({u->x,u->y})==state);});
    bind("UnitShareVision","nothing",{"unit","player","boolean"},[this](auto& vm,auto a){if(alive(a[0].bits,NativeKind::Unit)){auto owner=playerId(a[1]);auto& u=*units_.at(a[0].bits);if(a[2].bits)u.visionPlayers.insert(owner);else u.visionPlayers.erase(owner);++fogRevision_;}return vm.nothing();});
}
